select public.add_site_release('1.11.0','Защита от списывания в билетах классу',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: билет можно закрывать за выходы (3 раза или 10 секунд).'),
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: копирование текста запрещено, попытки видны преподавателю.'),
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: режим «Без возврата к вопросам».'),
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: приглашение учеников прошлого запуска через бота.'),
    jsonb_build_object('kind','new','scope','bot','min_rank',1,'text','Ученик заранее видит правила билета о выходах и копировании.'),
    jsonb_build_object('kind','new','scope','bot','min_rank',1,'text','Билет открывается на весь экран и помечен именем ученика.'),
    jsonb_build_object('kind','new','scope','site','min_rank',2,'text','«Качество банка»: можно проверить одну главу.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',4,'text','Режим НЦТ: сложность заданий включается переключателем.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','Сайт открывается при слабой связи и обновляется сам.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','Новый шрифт Inter: страницы открываются быстрее.'),
    jsonb_build_object('kind','improved','scope','app','min_rank',1,'text','Мини-приложение и билет в Telegram открываются быстрее.'),
    jsonb_build_object('kind','improved','scope','app','min_rank',1,'text','Проверка работ: цифры в открытых ответах распознаются точнее.')
  ),
  '2026-11-26 18:00:00+05');

select public.add_site_tip('1.11.0', 'В «Билетах классу» перед «Начать» стоит галочка «Закрывать билет за выходы»: после 3 выходов или 10 секунд вне страницы билет ученика закроется сам. Если это случайность, верните ученика кнопкой «Вернуть в билет».', 'nav-exams', 'exams', 1::smallint, '2026-11-26 18:00:00+05');
select public.add_site_tip('1.11.0', 'В таблице запуска «Билетов классу» есть столбец «Копировал»: он показывает, сколько раз ученик пытался скопировать текст билета. Снимок экрана так не поймать — следите и за столбцом «Уходил».', 'nav-exams', 'exams', 1::smallint, '2026-11-26 18:00:00+05');
select public.add_site_tip('1.11.0', 'В «Билетах классу» перед «Начать» можно поставить галочку «Без возврата к вопросам»: ученики будут отвечать по порядку и не смогут вернуться назад, чтобы расставить чужие ответы.', 'nav-exams', 'exams', 1::smallint, '2026-11-26 18:00:00+05');
select public.add_site_tip('1.11.0', 'Не нужно заново рассылать ссылку классу: в окне запуска «Билетов классу» нажмите «Пригласить учеников прошлого запуска», отметьте нужных — бот пришлёт им ссылку сам.', 'nav-exams', 'exams', 1::smallint, '2026-11-26 18:00:00+05');
